.scroll {
  position: relative;
  display: flex;
  flex: 1;

  .scroll_content {
    flex: 1;
    overflow: auto;

    > * {
      flex-shrink: 0;
    }

    /* use custom scrollbar */
    scrollbar-width: none;
    &::-webkit-scrollbar {
      display: none;
    }
  }
  .scroll_vertical_scrollbar {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    z-index: 100;
  }
  .scroll_vertical_track {
    width: 0.75rem;
    height: 100%;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] {
      opacity: 1;
    }
  }
  .scroll_vertical_thumb {
    width: 100%;
    background-color: var(--color-scrollbar-thumb);
  }
  .scroll_horizontal_scrollbar {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 100;
  }
  .scroll_horizontal_track {
    width: 100%;
    height: 0.75rem;
    opacity: 0;
    transition-property: opacity;
    transition-duration: 0.5s;

    &[show] {
      opacity: 1;
    }
  }
  .scroll_horizontal_thumb {
    height: 100%;
    background-color: var(--color-scrollbar-thumb);
  }
}

