type checkbox = {
  checked: boolean
  set_checked: (checked: boolean) => void
  [key: Key]: any
}

export function checkbox({ checked, set_checked, ...props }: checkbox) {
  function handle_change(event) {
    set_checked(event.target.checked)
  }

  return h('input.checkbox', {
    ...props,
    type: 'checkbox',
    checked,
    onchange: handle_change,
  })
}

type switch_props = {
  checked: boolean
  set_checked: (checked: boolean) => void
  children?: any
  [key: Key]: any
}

export function switch_component({
  checked,
  set_checked,
  children,
  ...props
}: switch_props) {
  function handle_click() {
    set_checked(!checked)
  }

  return h(
    'button.switch',
    {
      ...props,
      type: 'button',
      role: 'switch',
      'aria-checked': checked,
      checked,
      onclick: handle_click,
    },
    h('span.switch_thumb'),
    children,
  )
}

type select_option = {
  value: string
  label: string
}

type select_props = {
  value: string
  set_value: (value: string) => void
  options: select_option[]
  [key: Key]: any
}

export function select({ value, set_value, options, ...props }: select_props) {
  function handle_change(event) {
    set_value(event.target.value)
  }

  return h(
    'select.select',
    { ...props, value, onchange: handle_change },
    ...map(options, ({ value, label }) => h('option', { value }, label)),
  )
}

type radio_option = {
  value: string
  label: string
}

type radio_group_props = {
  value: string
  set_value: (value: string) => void
  options: radio_option[]
  name?: string
  [key: Key]: any
}

export function radio_group({
  value,
  set_value,
  options,
  name = 'radio_group',
  ...props
}: radio_group_props) {
  function handle_change(event) {
    set_value(event.target.value)
  }

  return h(
    'div.radio_group',
    props,
    ...map(options, (option) =>
      h(
        'label.radio_group_option',
        h('input.radio_group_input', {
          type: 'radio',
          name,
          value: option.value,
          checked: value === option.value,
          onchange: handle_change,
        }),
        h('span.radio_group_label', option.label),
      ),
    ),
  )
}

type slider_props = {
  value: number
  set_value: (value: number) => void
  min?: number
  max?: number
  step?: number
  [key: Key]: any
}

export function slider({
  value,
  set_value,
  min = 0,
  max = 100,
  step = 1,
  ...props
}: slider_props) {
  function handle_change(event) {
    set_value(Number(event.target.value))
  }

  return h('input.slider', {
    ...props,
    type: 'range',
    value,
    min,
    max,
    step,
    onchange: handle_change,
  })
}

